/* eslint-disable */
import React from "react";
import classNames from "classnames";

export default function PrettyCalendar({
    year = 2023,
    month = 2,
    selectedDay = 20,
    title = "Un jour spécial pour ?",
    birthdayLabel = "Anniversaire",
}) {
    // noms abrégés des jours
    const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    const nbDays = new Date(year, month, 0).getDate(); // nombre de jours du mois
    const firstDay = new Date(year, month - 1, 1).getDay(); // jour de départ (0 = dimanche)

    const dates = Array.from({ length: firstDay + nbDays }, (_, i) =>
        i < firstDay ? "" : i - firstDay + 1
    );

    return (
        <div className="bg-white rounded-2xl shadow-lg p-6">
            <h3 className="text-[#1c2b68] font-semibold text-xl mb-4">{title}</h3>
            {/* en-tête mois */}
            <div className="text-center text-blueGray-500 font-medium mb-2">
                {new Date(year, month - 1).toLocaleString("default", { month: "long" })} {year}
            </div>

            {/* jours de la semaine */}
            <div className="grid grid-cols-7 text-xs text-blueGray-400 mb-2">
                {days.map((d) => (
                    <div key={d} className="uppercase text-center">{d}</div>
                ))}
            </div>

            {/* grille des jours */}
            <div className="grid grid-cols-7 gap-y-2 text-sm">
                {dates.map((d, i) => (
                    <div
                        key={i}
                        className={classNames(
                            "h-8 w-8 mx-auto flex items-center justify-center rounded-full",
                            d === selectedDay
                                ? "bg-[#1c2b68] text-white font-bold shadow-md"
                                : d
                                    ? "text-blueGray-600 hover:bg-blueGray-100 cursor-pointer"
                                    : ""
                        )}
                    >
                        {d}
                    </div>
                ))}
            </div>

            {/* info anniversaire */}
            <div className="mt-4 text-center text-sm text-blueGray-700">
                🎉 {birthdayLabel}
            </div>
        </div>
    );
}
